import logging

from ta_moler.device.nokia_unix_remote import NokiaUnixRemote
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class cFZC(NokiaUnixRemote):
    r"""
    Cfzc device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      CFZC_PROXY_PC:
        DEVICE_CLASS: ta_moler.device.cfzc.cFZC
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: "proxy_pc#"
                host: proxy_pc_host
                login: proxy_pc_login
                password: password
          PROXY_PC:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: host_ip
                login: login
                password: password
                expected_prompt: remote_prompt
          FCPU:
            UNIX_REMOTE:
              command_params:
                expected_prompt: remote_prompt
          UNIX_REMOTE:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc#
    -without PROXY_PC:
      CFZC:
        DEVICE_CLASS: ta_moler.device.cfzc.cFZC
        CONNECTION_HOPS:
          UNIX_LOCAL:
            UNIX_REMOTE:
              execute_command: ssh
              command_params:
                host: host_ip
                login: login
                password: password
                expected_prompt: remote_prompt
          FCPU:
            UNIX_REMOTE:
              command_params:
                expected_prompt: remote_prompt
    """

    fcpu = "FCPU"
    fzbu = "FZBU"
    fsclish = "FSCLISH"
    trmsg = "TRMSG"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else cFZC.fcpu
        super(cFZC, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection, io_type=io_type,
                                   variant=variant, io_constructor_kwargs=io_constructor_kwargs,
                                   initial_state=initial_state, lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.cfzc')

    def _get_cfzc_default_sm_configuration(self):
        config = {
            cFZC.connection_hops: {
                cFZC.unix_remote: {  # from
                    cFZC.fcpu: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^\[root\@FCPU-0.*\/',
                            "login": "_nokfsoperator",
                            "password": ["_nokfsoperator", "root"],
                            "target_newline": "\n",
                            "host": "192.168.255.129",
                            "allowed_newline_after_prompt": True,
                            "set_prompt": r'export PS1="${PS1::-4} # "',
                        },
                        "required_command_params": [
                        ]
                    },
                },
                cFZC.fcpu: {  # from
                    cFZC.unix_remote: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                            "target_newline": "\n"
                        },
                        "required_command_params": [
                            "expected_prompt"
                        ]
                    },
                    cFZC.fzbu: {  # to
                        "execute_command": "ssh",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^\[root\@FZBU-0.*\/',
                            "host": "fzbu-0",
                            "login": "",
                            "password": "",
                            "target_newline": "\n",
                            "allowed_newline_after_prompt": True,
                            "set_prompt": r'export PS1="${PS1::-4} # "',
                        },
                        "required_command_params": [
                        ]
                    },
                    cFZC.fsclish: {  # to
                        "execute_command": "fsclish",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'root\@FCPU-\d+\s*\[(cFZC-)?\d+\]\s*\>'
                        },
                        "required_command_params": [
                        ]
                    },
                    cFZC.trmsg: {  # to
                        "execute_command": "trmsg",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'trmsg#'
                        },
                        "required_command_params": [
                        ]
                    },
                },
                cFZC.fzbu: {
                    cFZC.fcpu: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^\[root\@FCPU-0.*\/',
                            "target_newline": "\n"
                        },
                        "required_command_params": [
                        ]
                    },
                },
                cFZC.fsclish: {
                    cFZC.fcpu: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^\[root\@FCPU-0.*\/',
                            "target_newline": "\n"
                        },
                        "required_command_params": [
                        ]
                    },
                },
                cFZC.trmsg: {
                    cFZC.fcpu: {  # to
                        "execute_command": "exit",  # using command
                        "command_params": {  # with parameters
                            "expected_prompt": r'^\[root\@FCPU-0.*\/',
                            "target_newline": "\n"
                        },
                        "required_command_params": [
                        ]
                    },
                }
            }
        }
        return config

    @mark_to_call_base_class_method_with_same_name
    def _get_default_sm_configuration_with_proxy_pc(self):
        """
        Return State Machine default configuration with proxy_pc state.

        :return: default sm configuration with proxy_pc state.
        """
        return self._get_cfzc_default_sm_configuration()

    def _prepare_cfzc_transitions(self):
        transitions = {
            cFZC.unix_remote: {
                cFZC.fcpu: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            cFZC.fcpu: {
                cFZC.unix_remote: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                cFZC.fzbu: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                cFZC.fsclish: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                },
                cFZC.trmsg: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                }
            },
            cFZC.fzbu: {
                cFZC.fcpu: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            cFZC.fsclish: {
                cFZC.fcpu: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            cFZC.trmsg: {
                cFZC.fcpu: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        return self._prepare_cfzc_transitions()

    def _prepare_cfzc_state_prompts(self):
        state_prompts = {
            cFZC.fcpu:
                self._configurations[cFZC.connection_hops][cFZC.unix_remote][cFZC.fcpu][
                    "command_params"]["expected_prompt"],
            cFZC.fzbu:
                self._configurations[cFZC.connection_hops][cFZC.fcpu][cFZC.fzbu][
                    "command_params"]["expected_prompt"],
            cFZC.fsclish:
                self._configurations[cFZC.connection_hops][cFZC.fcpu][cFZC.fsclish][
                    "command_params"]["expected_prompt"],
            cFZC.trmsg:
                self._configurations[cFZC.connection_hops][cFZC.fcpu][cFZC.trmsg][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        return self._prepare_cfzc_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        return self._prepare_cfzc_state_prompts()

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            cFZC.not_connected: {
                cFZC.fcpu: cFZC.unix_local,
                cFZC.fzbu: cFZC.unix_local,
                cFZC.fsclish: cFZC.unix_local,
                cFZC.trmsg: cFZC.unix_local,
            },
            cFZC.unix_local: {
                cFZC.fcpu: cFZC.proxy_pc,
                cFZC.fzbu: cFZC.proxy_pc,
                cFZC.fsclish: cFZC.proxy_pc,
                cFZC.trmsg: cFZC.proxy_pc,
            },
            cFZC.unix_remote: {
                cFZC.fzbu: cFZC.fcpu,
                cFZC.fsclish: cFZC.fcpu,
                cFZC.trmsg: cFZC.fcpu,
            },
            cFZC.fcpu: {
                cFZC.not_connected: cFZC.unix_remote,
                cFZC.unix_local: cFZC.unix_remote,
                cFZC.unix_local_root: cFZC.unix_remote,
                cFZC.unix_remote_root: cFZC.unix_remote,
                cFZC.proxy_pc: cFZC.unix_remote
            },
            cFZC.fzbu: {
                cFZC.not_connected: cFZC.fcpu,
                cFZC.unix_local: cFZC.fcpu,
                cFZC.unix_remote: cFZC.fcpu,
                cFZC.fsclish: cFZC.fcpu,
                cFZC.trmsg: cFZC.fcpu,
                cFZC.unix_local_root: cFZC.fcpu,
                cFZC.unix_remote_root: cFZC.fcpu,
                cFZC.proxy_pc: cFZC.fcpu
            },
            cFZC.fsclish: {
                cFZC.not_connected: cFZC.fcpu,
                cFZC.unix_local: cFZC.fcpu,
                cFZC.unix_remote: cFZC.fcpu,
                cFZC.fzbu: cFZC.fcpu,
                cFZC.trmsg: cFZC.fcpu,
                cFZC.unix_local_root: cFZC.fcpu,
                cFZC.unix_remote_root: cFZC.fcpu,
                cFZC.proxy_pc: cFZC.fcpu
            },
            cFZC.trmsg: {
                cFZC.not_connected: cFZC.fcpu,
                cFZC.unix_local: cFZC.fcpu,
                cFZC.unix_remote: cFZC.fcpu,
                cFZC.fzbu: cFZC.fcpu,
                cFZC.fsclish: cFZC.fcpu,
                cFZC.unix_local_root: cFZC.fcpu,
                cFZC.unix_remote_root: cFZC.fcpu,
                cFZC.proxy_pc: cFZC.fcpu
            },
            cFZC.unix_local_root: {
                cFZC.fsclish: cFZC.unix_local,
                cFZC.trmsg: cFZC.unix_local,
                cFZC.fzbu: cFZC.unix_local,
                cFZC.fcpu: cFZC.unix_local,
            },
            cFZC.proxy_pc: {
                cFZC.fsclish: cFZC.unix_remote,
                cFZC.trmsg: cFZC.unix_remote,
                cFZC.fzbu: cFZC.unix_remote,
                cFZC.fcpu: cFZC.unix_remote,
            },
            cFZC.unix_remote_root: {
                cFZC.fsclish: cFZC.unix_remote,
                cFZC.trmsg: cFZC.unix_remote,
                cFZC.fzbu: cFZC.unix_remote,
                cFZC.fcpu: cFZC.unix_remote,
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(cFZC, self)._get_packages_for_state(state, observer)

        if not available:
            if state == cFZC.fcpu:
                available = {cFZC.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix',
                                         'ta_moler.cmd.shared.enblinux', 'ta_moler.cmd.cFZC.fcpu'],
                             cFZC.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.cFZC']}
            elif state == cFZC.fzbu:
                available = {cFZC.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.cFZC.fzbu'],
                             cFZC.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.cFZC']}
            elif state == cFZC.fsclish:
                available = {cFZC.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix',
                                         'ta_moler.cmd.shared.fsclish'],
                             cFZC.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.cFZC']}
            elif state == cFZC.trmsg:
                available = {cFZC.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.cFZC.trmsg'],
                             cFZC.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.cFZC']}
            if available:
                return available[observer]

        return available
